import itertools
import random

def has_cycle_of_length(G, length):
    """Check if graph G (as set of edges) has a cycle of given length."""
    n = max(max(u,v) for u,v in G) + 1 if G else 0
    adj = {i: set() for i in range(n)}
    for u,v in G:
        adj[u].add(v)
        adj[v].add(u)

    # Use DFS to find cycles of specific length
    # We'll do a brute-force search for small lengths
    vertices = list(range(n))

    # For cycle length L, we can check all sequences of L distinct vertices
    # But that's expensive. Let's do BFS limiting depth.
    # Actually, let's use a simple algorithm: for each starting vertex, do DFS keeping track of depth.

    for start in vertices:
        # DFS stack: (current, parent, depth, path)
        stack = [(start, -1, 0, [start])]
        visited_states = set()
        while stack:
            v, p, d, path = stack.pop()
            if d > length:
                continue
            for nb in adj[v]:
                if nb == p:
                    continue
                if nb == start and d >= 2 and d + 1 == length:
                    return True
                if nb not in path:
                    stack.append((nb, v, d+1, path + [nb]))
    return False

def girth_at_least(G, g):
    """Check if all cycles have length >= g."""
    for L in range(3, g):
        if has_cycle_of_length(G, L):
            return False
    return True

def is_colorable_with_k(G, k):
    """Check if graph is k-colorable using simple backtracking."""
    n = max(max(u,v) for u,v in G) + 1 if G else 0
    adj = {i: set() for i in range(n)}
    for u,v in G:
        adj[u].add(v)
        adj[v].add(u)

    colors = [-1] * n

    def backtrack(idx):
        if idx == n:
            return True
        used = set()
        for nb in adj[idx]:
            if colors[nb] != -1:
                used.add(colors[nb])
        for c in range(k):
            if c not in used:
                colors[idx] = c
                if backtrack(idx+1):
                    return True
                colors[idx] = -1
        return False

    return backtrack(0)

# Let's try to construct a graph with girth >= 8
# We'll use a random search approach with some heuristics

import random
random.seed(42)

n = 15
target_edges = 24
max_attempts = 50000

best = None
best_edges = 0

for attempt in range(max_attempts):
    # Start with empty graph
    G = set()
    # Add edges randomly but avoid creating small cycles
    all_possible = [(i,j) for i in range(n) for j in range(i+1, n)]
    random.shuffle(all_possible)

    for u,v in all_possible:
        # Tentatively add
        G.add((u,v))
        # Check girth
        if not girth_at_least(G, 8):
            G.remove((u,v))
            continue
        # Check 4-colorable
        if not is_colorable_with_k(G, 4):
            G.remove((u,v))
            continue

    if len(G) >= target_edges:
        print(f"Found! Attempt {attempt}, edges={len(G)}")
        print(sorted(G))
        break

    if len(G) > best_edges:
        best_edges = len(G)
        best = set(G)
        print(f"Attempt {attempt}: best edges = {best_edges}")

print(f"Best found: {best_edges} edges")
if best:
    print(sorted(best))
